#!/usr/bin/env python3
"""Persistent HTTP key-value service.

Dependency-free Python 3.11+ HTTP service exposing a small JSON key-value API
with optional per-entry TTL, on-disk persistence and clean shutdown.

Usage:
    python3 server.py --host 127.0.0.1 --port PORT --data PATH
"""

from __future__ import annotations

import argparse
import json
import os
import signal
import sys
import threading
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

MAX_BODY_BYTES = 1 * 1024 * 1024  # 1 MiB request body limit


class Store:
    """Thread-safe in-memory key-value store with TTL and atomic persistence."""

    def __init__(self, path: str) -> None:
        self._path = path
        self._lock = threading.RLock()
        self._data: dict[str, tuple[float, float]] = {}  # key -> (value, expire_at)
        self._load()

    def _load(self) -> None:
        if not self._path or not os.path.exists(self._path):
            return
        try:
            with open(self._path, "r", encoding="utf-8") as fh:
                raw = json.load(fh)
        except (OSError, ValueError) as exc:
            _log(f"failed to load state from {self._path}: {exc}")
            return
        if not isinstance(raw, dict):
            _log(f"state file {self._path} is not a JSON object; ignoring")
            return
        now = time.time()
        for key, entry in raw.items():
            if not isinstance(entry, dict) or "value" not in entry:
                continue
            expire_at = entry.get("expire_at")
            if expire_at is not None:
                if not isinstance(expire_at, (int, float)):
                    continue
                if expire_at <= now:
                    continue
            self._data[key] = (entry["value"], float("inf") if expire_at is None else float(expire_at))

    def _persist_locked(self) -> None:
        now = time.time()
        serializable: dict[str, dict] = {}
        for key, (value, expire_at) in self._data.items():
            if expire_at != float("inf") and expire_at <= now:
                continue
            serializable[key] = {
                "value": value,
                "expire_at": None if expire_at == float("inf") else expire_at,
            }
        tmp_path = self._path + ".tmp"
        try:
            with open(tmp_path, "w", encoding="utf-8") as fh:
                json.dump(serializable, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, self._path)
        except OSError as exc:
            _log(f"failed to persist state to {self._path}: {exc}")

    def _is_live(self, key: str, now: float) -> bool:
        entry = self._data.get(key)
        if entry is None:
            return False
        _, expire_at = entry
        if expire_at != float("inf") and expire_at <= now:
            del self._data[key]
            return False
        return True

    def put(self, key: str, value, ttl_seconds) -> bool:
        """Create or replace a key. Returns True if created, False if replaced."""
        with self._lock:
            now = time.time()
            existed = self._is_live(key, now)
            expire_at = float("inf") if ttl_seconds is None else now + float(ttl_seconds)
            self._data[key] = (value, expire_at)
            self._persist_locked()
            return not existed

    def get(self, key: str):
        with self._lock:
            now = time.time()
            if not self._is_live(key, now):
                return None, False
            value, _ = self._data[key]
            return value, True

    def delete(self, key: str) -> bool:
        with self._lock:
            now = time.time()
            if not self._is_live(key, now):
                return False
            del self._data[key]
            self._persist_locked()
            return True

    def keys(self) -> list[str]:
        with self._lock:
            now = time.time()
            live = [k for k in self._data if self._is_live(k, now)]
            return sorted(live)


def _log(message: str) -> None:
    print(message, file=sys.stderr, flush=True)


class KVError(Exception):
    def __init__(self, status: int, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.message = message


def _error_body(message: str) -> bytes:
    return json.dumps({"error": message}).encode("utf-8")


class Handler(BaseHTTPRequestHandler):
    server_version = "http-kv/1.0"
    protocol_version = "HTTP/1.1"

    # Silence default request logging; route diagnostics through _log.
    def log_message(self, format, *args):  # noqa: A002
        return

    # ---- helpers -------------------------------------------------------

    @property
    def store(self) -> Store:
        return self.server.store  # type: ignore[attr-defined]

    def _send_json(self, status: int, payload) -> None:
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _send_empty(self, status: int) -> None:
        self.send_response(status)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def _read_body(self) -> bytes:
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError as exc:
            raise KVError(400, f"invalid Content-Length: {exc}")
        if length < 0:
            raise KVError(400, "negative Content-Length")
        if length > MAX_BODY_BYTES:
            raise KVError(413, "request body too large")
        if length == 0:
            return b""
        body = self.rfile.read(length)
        if len(body) != length:
            raise KVError(400, "truncated request body")
        return body

    def _parse_json_body(self) -> dict:
        raw = self._read_body()
        if raw == b"":
            raise KVError(400, "request body is required")
        try:
            data = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, ValueError):
            raise KVError(400, "malformed JSON")
        if not isinstance(data, dict):
            raise KVError(400, "JSON body must be an object")
        return data

    # ---- routing -------------------------------------------------------

    def do_GET(self) -> None:  # noqa: N802
        try:
            self._route("GET")
        except KVError as exc:
            self._send_json(exc.status, {"error": exc.message})
        except Exception as exc:  # pragma: no cover - defensive
            _log(f"internal error: {exc}")
            self._send_json(500, {"error": "internal server error"})

    def do_PUT(self) -> None:  # noqa: N802
        try:
            self._route("PUT")
        except KVError as exc:
            self._send_json(exc.status, {"error": exc.message})
        except Exception as exc:  # pragma: no cover - defensive
            _log(f"internal error: {exc}")
            self._send_json(500, {"error": "internal server error"})

    def do_DELETE(self) -> None:  # noqa: N802
        try:
            self._route("DELETE")
        except KVError as exc:
            self._send_json(exc.status, {"error": exc.message})
        except Exception as exc:  # pragma: no cover - defensive
            _log(f"internal error: {exc}")
            self._send_json(500, {"error": "internal server error"})

    def _route(self, method: str) -> None:
        parsed = urllib.parse.urlsplit(self.path)
        path = parsed.path
        if path == "/health" and method == "GET":
            self._send_json(200, {"status": "ok"})
            return
        if path == "/v1/keys" and method == "GET":
            self._send_json(200, {"keys": self.store.keys()})
            return
        if path.startswith("/v1/kv/"):
            key_segment = path[len("/v1/kv/"):]
            key = self._decode_key(key_segment)
            if method == "GET":
                value, found = self.store.get(key)
                if not found:
                    raise KVError(404, "key not found")
                self._send_json(200, {"key": key, "value": value})
                return
            if method == "DELETE":
                if self.store.delete(key):
                    self._send_empty(204)
                else:
                    raise KVError(404, "key not found")
                return
            if method == "PUT":
                self._handle_put(key)
                return
            raise KVError(405, "method not allowed")
        raise KVError(404, "unknown route")

    def _decode_key(self, segment: str) -> str:
        if segment == "":
            raise KVError(400, "empty key is not allowed")
        if "/" in segment:
            raise KVError(400, "key must not contain '/'")
        try:
            key = urllib.parse.unquote(segment, encoding="utf-8", errors="strict")
        except UnicodeDecodeError:
            raise KVError(400, "key is not valid UTF-8")
        if key == "":
            raise KVError(400, "empty key is not allowed")
        return key

    def _handle_put(self, key: str) -> None:
        data = self._parse_json_body()
        if "value" not in data:
            raise KVError(400, "field 'value' is required")
        value = data["value"]
        ttl_seconds = data.get("ttl_seconds")
        if ttl_seconds is not None:
            if isinstance(ttl_seconds, bool) or not isinstance(ttl_seconds, (int, float)):
                raise KVError(400, "ttl_seconds must be a number")
            if not (ttl_seconds == ttl_seconds and ttl_seconds != float("inf")):  # NaN/inf check
                raise KVError(400, "ttl_seconds must be finite")
            if ttl_seconds <= 0:
                raise KVError(400, "ttl_seconds must be greater than zero")
        created = self.store.put(key, value, ttl_seconds)
        self._send_json(201 if created else 200, {"key": key, "value": value})


class KVServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, addr, store: Store) -> None:
        super().__init__(addr, Handler)
        self.store = store
        self._shutdown_event = threading.Event()

    def serve_forever(self, poll_interval: float = 0.5) -> None:  # type: ignore[override]
        try:
            super().serve_forever(poll_interval=poll_interval)
        finally:
            self._shutdown_event.set()


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Persistent HTTP key-value service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=0)
    parser.add_argument("--data", default="kv.json")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    store = Store(args.data)
    server = KVServer((args.host, args.port), store)

    def _handle_sigterm(signum, _frame) -> None:  # noqa: ANN001
        _log(f"received signal {signum}, shutting down")
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, _handle_sigterm)
    signal.signal(signal.SIGINT, _handle_sigterm)

    actual_port = server.server_address[1]
    print(f"LISTENING {actual_port}", flush=True)
    _log(f"serving on {args.host}:{actual_port}, data={args.data}")
    try:
        server.serve_forever()
    finally:
        server.server_close()
        _log("server stopped")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

